diff --git a/tests/repro/no-loss-of-precision-19957.js b/tests/repro/no-loss-of-precision-19957.js
new file mode 100644
index 0000000..d7bf2df
--- /dev/null
+++ b/tests/repro/no-loss-of-precision-19957.js
@@ -0,0 +1,41 @@
+/**
+ * @fileoverview Reproduction for no-loss-of-precision false positives on
+ * exponent literals whose coefficient has trailing zeros (e.g. 9.000e+3).
+ * Run: node tests/repro/no-loss-of-precision-19957.js
+ */
+"use strict";
+
+const { Linter } = require("../../lib/api");
+
+const linter = new Linter();
+const cases = [
+	["9.000e+3", false],
+	["9.000e3", false],
+	["9.0000e4", false],
+	["9.000e4", false],
+	["9.0000e5", false],
+	["1.0e1", false],
+	["1.00e2", false],
+	["12.30e2", false],
+	["9007199254740993", true], // control: genuine precision loss
+];
+
+let unexpected = 0;
+
+for (const [literal, shouldReport] of cases) {
+	const messages = linter.verify(`const x = ${literal};`, {
+		rules: { "no-loss-of-precision": "error" },
+	});
+	const reported = messages.some(m => m.ruleId === "no-loss-of-precision");
+	const ok = reported === shouldReport;
+
+	if (!ok) {
+		unexpected++;
+	}
+	console.log(
+		`${ok ? "OK  " : "BUG "} ${literal.padEnd(18)} value=${String(Number(literal)).padEnd(18)} reported=${reported} expected=${shouldReport}`,
+	);
+}
+
+console.log(`\n${unexpected} unexpected result(s)`);
+process.exitCode = unexpected ? 1 : 0;
